const crypto = require('crypto');
const envelope = $json;
const headers = envelope.headers ?? {};
const expectedWebhookSecret = $env.CUSTOM_WA_WEBHOOK_SECRET;
const receivedWebhookSecret = headers['x-webhook-secret'] ?? headers['x-api-key'] ?? String(headers.authorization ?? '').replace(/^Bearer\s+/i, '');
if (!expectedWebhookSecret || !receivedWebhookSecret) throw new Error('Falta autenticacion del webhook casero');
const expectedBuffer = Buffer.from(expectedWebhookSecret);
const receivedBuffer = Buffer.from(String(receivedWebhookSecret));
if (expectedBuffer.length !== receivedBuffer.length || !crypto.timingSafeEqual(expectedBuffer, receivedBuffer)) throw new Error('Webhook casero no autorizado');
const source = envelope.body ?? envelope;
const message = source.message ?? source.data ?? source;
const media = message.media ?? message.file ?? message.audio ?? message.image ?? message.document ?? {};
const mediaObject = typeof media === 'string' ? { url: media } : media;
const rawType = String(message.type ?? source.type ?? (message.audio ? 'audio' : message.file ? 'file' : 'text')).toLowerCase();
const providerType = rawType === 'voice' ? 'audio' : rawType;
const acceptedTypes = ['text', 'image', 'document', 'interactive'];
const messageType = providerType === 'file' ? 'document' : acceptedTypes.includes(providerType) ? providerType : 'unknown';
const text = typeof message.text === 'object' ? message.text.body : (message.text ?? message.caption ?? source.text ?? '');
const payload = {
  wa_id: String(message.from ?? message.sender ?? message.phone ?? source.from ?? source.sender ?? ''),
  message_id: String(message.id ?? message.message_id ?? source.event_id ?? source.id ?? ''),
  message_type: messageType,
  provider_message_type: providerType,
  text: String(text ?? ''),
  media_id: String(mediaObject.id ?? mediaObject.file_id ?? message.media_id ?? mediaObject.url ?? ''),
  media_base64: String(mediaObject.base64 ?? mediaObject.data ?? message.media_base64 ?? ''),
  mime_type: String(mediaObject.mime_type ?? mediaObject.mimetype ?? message.mime_type ?? ''),
  file_name: String(mediaObject.file_name ?? mediaObject.filename ?? message.file_name ?? '')
};
if (!payload.wa_id || !payload.message_id) throw new Error('Evento casero sin remitente o message_id');
const body = JSON.stringify(payload);
const timestamp = Math.floor(Date.now() / 1000).toString();
const nonce = crypto.createHash('sha256').update(payload.message_id).digest('hex').slice(0, 32);
const integrationSecret = $env.N8N_SHARED_SECRET;
if (!integrationSecret) throw new Error('Falta N8N_SHARED_SECRET');
const signature = crypto.createHmac('sha256', integrationSecret).update(`${timestamp}.${nonce}.${body}`).digest('hex');
return [{ json: { requestBody: payload, rawBody: body, headers: { timestamp, nonce, signature } } }];

const inbound = $('Adaptar y firmar').first().json.requestBody;
const messages = Array.isArray($json.messages) ? $json.messages : [];
return messages
  .filter((message) => message && typeof message.type === 'string')
  .map((message, index) => {
    const outbound = { to: inbound.wa_id, type: message.type, idempotency_key: `reply:${inbound.message_id}:${index}` };
    if (message.type === 'text') outbound.text = String(message.text ?? '').trim();
    if (message.file) outbound.file = message.file;
    if (message.audio) outbound.audio = message.audio;
    return { json: { rawBody: JSON.stringify(outbound), action: $json.action ?? null } };
  })
  .filter((item) => JSON.parse(item.json.rawBody).type !== 'text' || JSON.parse(item.json.rawBody).text);
